UPDATE mq_message_status
SET status = 5, update_time = NOW()
WHERE message_id = #{messageId}
  AND retry_count < #{maxRetryCount}
  AND (
      status IN (2, 4)
      OR (status IN (0, 5) AND TIMESTAMPDIFF(SECOND, update_time, NOW()) >= #{staleSeconds})
  )

