SELECT *
FROM mq_message_status
WHERE retry_count < #{maxRetryCount}
  AND message_body IS NOT NULL
  AND (
      status IN (2, 4)
      OR (status IN (0, 5) AND TIMESTAMPDIFF(SECOND, update_time, NOW()) >= #{staleSeconds})
  )
ORDER BY update_time ASC
LIMIT #{limit}

